        print(json.dumps({'trace_id': trace_id, **evidence}, indent=2))
        return 0 if evidence['dashboard_finalization'] == 'verified' else 3
    required = ['NEATLOGS_API_KEY']
    if not minimal:
        required += ['SENTINELOPS_MODEL', 'SENTINELOPS_MODEL_API_KEY']
